import React, { useEffect, useState } from 'react';
import axios from 'axios';

const MOCK_LEADERS = [
  { name: 'Arjun Sharma', xp: 4200, streak: 28, completed: 8, role: 'student' },
  { name: 'Priya Patel', xp: 3850, streak: 21, completed: 7, role: 'student' },
  { name: 'Carlos Rivera', xp: 3100, streak: 14, completed: 6, role: 'student' },
  { name: 'Liu Wei', xp: 2750, streak: 12, completed: 5, role: 'student' },
  { name: 'Amara Osei', xp: 2200, streak: 9, completed: 4, role: 'student' },
  { name: 'Sara Khan', xp: 1900, streak: 7, completed: 3, role: 'student' },
  { name: 'James O\'Brien', xp: 1450, streak: 5, completed: 3, role: 'student' },
  { name: 'Yuki Tanaka', xp: 1100, streak: 4, completed: 2, role: 'student' },
  { name: 'Fatima Hassan', xp: 850, streak: 3, completed: 2, role: 'student' },
  { name: 'Miguel Torres', xp: 600, streak: 2, completed: 1, role: 'student' },
];

const medals = ['🥇', '🥈', '🥉'];
const rankColors = ['#ffd700', '#c0c0c0', '#cd7f32'];

export default function LeaderboardPage() {
  const [leaders] = useState(MOCK_LEADERS);
  const [filter, setFilter] = useState('xp');
  const maxXP = Math.max(...leaders.map(l => l.xp));

  const sorted = [...leaders].sort((a, b) => b[filter] - a[filter]);

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      <div className="page-container" style={{ padding: '40px 24px', maxWidth: 860 }}>
        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: 48 }}>
          <div style={{ fontSize: 64, marginBottom: 12, animation: 'float 3s ease-in-out infinite' }}>🏆</div>
          <h1 style={{ fontSize: 'clamp(28px, 5vw, 48px)', fontWeight: 900, marginBottom: 8 }}>
            <span style={{ background: 'linear-gradient(135deg, #ffd700, #f72585)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Leaderboard</span>
          </h1>
          <p style={{ color: '#6b6490', fontSize: 16 }}>The most dedicated learners on Learnify</p>
        </div>

        {/* Top 3 Podium */}
        <div style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'center', gap: 16, marginBottom: 48, padding: '0 20px' }}>
          {[1, 0, 2].map(rank => {
            const learner = sorted[rank];
            if (!learner) return null;
            const heights = [160, 200, 130];
            const podiumHeight = heights[rank === 0 ? 1 : rank === 1 ? 0 : 2];
            return (
              <div key={rank} style={{ flex: 1, maxWidth: 200, display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{ fontSize: rank === 0 ? 28 : 20, marginBottom: 6 }}>{medals[rank]}</div>
                <div style={{
                  width: 52, height: 52, borderRadius: '50%',
                  background: `linear-gradient(135deg, ${rankColors[rank]}, #7c3aed)`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 20, fontWeight: 900, color: 'white', marginBottom: 8,
                  boxShadow: `0 0 20px ${rankColors[rank]}60`,
                  animation: rank === 0 ? 'pulse-glow 2s ease-in-out infinite' : 'none'
                }}>{learner.name.charAt(0)}</div>
                <div style={{ fontWeight: 800, fontSize: 14, color: '#f0eeff', marginBottom: 2, textAlign: 'center' }}>{learner.name.split(' ')[0]}</div>
                <div style={{ fontSize: 13, fontWeight: 700, color: rankColors[rank], marginBottom: 8 }}>⚡ {learner.xp} XP</div>
                <div style={{
                  width: '100%', height: podiumHeight, borderRadius: '12px 12px 0 0',
                  background: rank === 0 ? 'linear-gradient(180deg, rgba(255,215,0,0.3), rgba(255,215,0,0.1))' :
                    rank === 1 ? 'linear-gradient(180deg, rgba(192,192,192,0.2), rgba(192,192,192,0.05))' :
                    'linear-gradient(180deg, rgba(205,127,50,0.2), rgba(205,127,50,0.05))',
                  border: `1px solid ${rankColors[rank]}40`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 24, fontWeight: 900, color: rankColors[rank]
                }}>#{rank + 1}</div>
              </div>
            );
          })}
        </div>

        {/* Filter tabs */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 24 }}>
          {[['xp', '⚡ XP'], ['streak', '🔥 Streak'], ['completed', '✅ Completed']].map(([key, label]) => (
            <button key={key} onClick={() => setFilter(key)} style={{
              padding: '8px 20px', borderRadius: 100, border: 'none', cursor: 'pointer', fontWeight: 700, fontSize: 14, transition: 'all 0.2s',
              background: filter === key ? 'linear-gradient(135deg, #7c3aed, #a855f7)' : 'rgba(124,58,237,0.1)',
              color: filter === key ? 'white' : '#b8b0d8',
              boxShadow: filter === key ? '0 4px 20px rgba(124,58,237,0.4)' : 'none'
            }}>{label}</button>
          ))}
        </div>

        {/* Rankings List */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
          {sorted.map((learner, i) => (
            <div key={learner.name} className="glass glass-hover" style={{ padding: '16px 22px', borderRadius: 14, display: 'flex', alignItems: 'center', gap: 18, animation: `fadeUp 0.4s ease ${i * 0.06}s both`, border: i < 3 ? `1px solid ${rankColors[i]}30` : '1px solid rgba(124,58,237,0.2)' }}>
              <div style={{ width: 36, textAlign: 'center', fontSize: 20, fontWeight: 900, color: i < 3 ? rankColors[i] : '#6b6490', flexShrink: 0 }}>
                {i < 3 ? medals[i] : `#${i + 1}`}
              </div>
              <div style={{ width: 44, height: 44, borderRadius: '50%', background: `linear-gradient(135deg, ${i < 3 ? rankColors[i] : '#7c3aed'}, #a855f7)`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, fontWeight: 900, color: 'white', flexShrink: 0 }}>
                {learner.name.charAt(0)}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontWeight: 700, fontSize: 15, color: '#f0eeff', marginBottom: 4 }}>{learner.name}</div>
                {/* XP Bar */}
                <div style={{ height: 4, background: 'rgba(124,58,237,0.15)', borderRadius: 2, overflow: 'hidden', maxWidth: 200 }}>
                  <div style={{ height: '100%', width: `${(learner.xp / maxXP) * 100}%`, background: i < 3 ? `linear-gradient(90deg, ${rankColors[i]}, #7c3aed)` : 'linear-gradient(90deg, #7c3aed, #a855f7)', borderRadius: 2 }} />
                </div>
              </div>
              <div style={{ display: 'flex', gap: 20, flexShrink: 0 }}>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontWeight: 800, fontSize: 15, color: '#ffd700' }}>{learner.xp}</div>
                  <div style={{ fontSize: 10, color: '#6b6490' }}>XP</div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontWeight: 800, fontSize: 15, color: '#f72585' }}>{learner.streak}</div>
                  <div style={{ fontSize: 10, color: '#6b6490' }}>Streak</div>
                </div>
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontWeight: 800, fontSize: 15, color: '#00f5d4' }}>{learner.completed}</div>
                  <div style={{ fontSize: 10, color: '#6b6490' }}>Done</div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
